let saved={};try{saved=JSON.parse(localStorage.getItem('island-settings')||'{}')}catch{}let code=/^\d{4}$/.test(saved.code)?saved.code:'2026',hint=saved.hint||'四个角色各有一条线索。请先找出缺失词，再按主持人给出的顺序组合对应数字。',value='',attempts=0,unlocked=false,sound=false,ctx,videoUrl,timer;
const $=id=>document.getElementById(id);function beep(ok=true){if(!sound)return;try{ctx ||= new (window.AudioContext||window.webkitAudioContext)();ctx.resume();const o=ctx.createOscillator(),g=ctx.createGain();o.connect(g);g.connect(ctx.destination);o.frequency.value=ok?660:180;g.gain.setValueAtTime(.035,ctx.currentTime);g.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+.12);o.start();o.stop(ctx.currentTime+.12)}catch{}}
function render(){document.querySelectorAll('.digit').forEach((e,i)=>{e.textContent=value[i]||'—';e.classList.toggle('empty',!value[i]);e.classList.toggle('active',i===value.length&&!unlocked)})}function status(text,error=false){$('status').textContent=text;$('status').classList.toggle('error',error)}function key(k){if(unlocked)return;if(k==='clear')value='';else if(k==='back')value=value.slice(0,-1);else if(value.length<4)value+=k;beep();render();status('输入完成后，点击验证密码')}
$('keys').onclick=e=>{const b=e.target.closest('[data-key]');if(b)key(b.dataset.key)};document.addEventListener('keydown',e=>{if(document.querySelector('dialog[open]')||/INPUT|TEXTAREA/.test(e.target.tagName)||e.ctrlKey||e.metaKey||e.altKey)return;if(/^\d$/.test(e.key)){e.preventDefault();key(e.key)}else if(e.key==='Backspace'){e.preventDefault();key('back')}else if(e.key==='Escape')key('clear');else if(e.key==='Enter'&&e.target.tagName!=='BUTTON'){e.preventDefault();verify()}});
function startPlayback(){clearInterval(timer);let t=0;$('timestamp').textContent='2026 / 11 / 20 02:14:00';timer=setInterval(()=>{t++;$('timestamp').textContent='2026 / 11 / 20 02:'+String(14+Math.floor(t/60)).padStart(2,'0')+':'+String(t%60).padStart(2,'0')},1000);const svg=document.querySelector('.scene');svg.style.display=videoUrl?'none':'';if(videoUrl){let v=$('customVideo');if(!v){v=document.createElement('video');v.id='customVideo';v.style.cssText='position:absolute;inset:0;width:100%;height:100%;object-fit:contain';v.controls=true;v.playsInline=true;$('monitor').append(v)}v.src=videoUrl;v.muted=!sound;v.play().catch(()=>status('已解锁，点击视频播放按钮'))}else{const f=document.querySelector('.figure');f.style.animation='none';void f.getBoundingClientRect();f.style.animation=''}}
function verify(){if(unlocked)return;if(value.length!==4){status('请输入完整的四位数字',true);return}attempts++;$('attempts').textContent=String(attempts).padStart(2,'0');if(value!==code){beep(false);value='';render();status('密码不正确，请重新检查线索',true);return}unlocked=true;beep();document.body.classList.add('success');$('lockTag').textContent='UNLOCKED';$('rec').textContent='● REC / 回放';$('feedStatus').textContent='ARCHIVE PLAYBACK';$('feedCaption').textContent='档案已解密 / 中央控制室';$('submit').textContent='档案已解锁';$('submit').disabled=true;$('revealed').classList.remove('hidden');status('验证成功，监控档案已恢复');render();startPlayback()}
$('submit').onclick=verify;$('hint').onclick=()=>{$('hintText').textContent=hint;$('hintDialog').showModal()};$('closeHint').onclick=()=>$('hintDialog').close();$('settings').onclick=()=>{$('newCode').value=code;$('newHint').value=hint;$('settingsDialog').showModal()};$('cancelSettings').onclick=()=>$('settingsDialog').close();$('settingsForm').onsubmit=e=>{e.preventDefault();const next=$('newCode').value;if(!/^\d{4}$/.test(next))return;code=next;hint=$('newHint').value.trim()||'请与其他玩家交换线索，按角色卡指定的顺序组合数字。';try{localStorage.setItem('island-settings',JSON.stringify({code,hint}))}catch{}const file=$('videoFile').files[0];if(file){if(videoUrl)URL.revokeObjectURL(videoUrl);videoUrl=URL.createObjectURL(file)}clearInterval(timer);$('customVideo')?.remove();document.querySelector('.scene').style.display='';unlocked=false;value='';attempts=0;document.body.classList.remove('success');$('lockTag').textContent='LOCKED';$('rec').textContent='● LOCKED';$('feedStatus').textContent='ENCRYPTED FEED';$('timestamp').textContent='---- / -- / -- --:--:--';$('feedCaption').textContent='加密监控档案 / 仅限授权访问';$('submit').textContent='验证密码';$('submit').disabled=false;$('attempts').textContent='00';$('revealed').classList.add('hidden');status('设置已保存，等待输入密码');render();$('settingsDialog').close()};$('sound').onclick=()=>{sound=!sound;$('sound').textContent='声音：'+(sound?'开':'关');$('sound').setAttribute('aria-pressed',String(sound));if($('customVideo'))$('customVideo').muted=!sound;beep()};$('truth').onclick=()=>$('truthDialog').showModal();$('closeTruth').onclick=()=>$('truthDialog').close();$('replay').onclick=startPlayback;
